  // src/ts/i18n/i18n.ts
  var STORAGE_KEY = "atl-locale";
  var DEFAULT_LOCALE = "pt";
  var SUPPORTED = ["pt", "en"];
  var LOCALES = { pt, en };
  var currentLocale = DEFAULT_LOCALE;
  function t(key, vars) {
    const translations = LOCALES[currentLocale];
    let value = translations[key] ?? LOCALES[DEFAULT_LOCALE][key] ?? key;
    if (vars) {
      Object.entries(vars).forEach(([k, v]) => {
        value = value.replace(new RegExp(`{{${k}}}`, "g"), v);
      });
    }
    return value;
  }
  function setLocale(locale) {
    if (!SUPPORTED.includes(locale)) return;
    currentLocale = locale;
    localStorage.setItem(STORAGE_KEY, locale);
    applyTranslations();
    updateHtmlLang();
    updateLanguageSwitcher();
    document.dispatchEvent(new CustomEvent("localeChanged", { detail: { locale } }));
  }
  function detectLocale() {
    const stored = localStorage.getItem(STORAGE_KEY);
    if (stored && SUPPORTED.includes(stored)) return stored;
    const browser = navigator.language.slice(0, 2);
    if (SUPPORTED.includes(browser)) return browser;
    return DEFAULT_LOCALE;
  }
  function applyTranslations() {
    document.querySelectorAll("[data-i18n]").forEach((el) => {
      const key = el.dataset.i18n;
      el.textContent = t(key);
    });
    document.querySelectorAll("[data-i18n-html]").forEach((el) => {
      const key = el.dataset.i18nHtml;
      el.innerHTML = t(key);
    });
    document.querySelectorAll(
      "[data-i18n-placeholder]"
    ).forEach((el) => {
      const key = el.dataset.i18nPlaceholder;
      el.placeholder = t(key);
    });
    document.querySelectorAll("[data-i18n-aria-label]").forEach((el) => {
      const key = el.dataset.i18nAriaLabel;
      el.setAttribute("aria-label", t(key));
    });
    document.querySelectorAll("[data-i18n-title]").forEach((el) => {
      const key = el.dataset.i18nTitle;
      el.setAttribute("title", t(key));
    });
  }
  function updateHtmlLang() {
    document.documentElement.lang = currentLocale;
  }
